INSERT INTO `faqs` (`id`, `name`, `description`, `status`, `created_at`, `updated_at`) VALUES
(1, 'What countries do we export to?', 'We export premium bedsheets and linens worldwide, including the USA, Canada, Australia, Kenya, and many other countries.', 'active', '2026-02-05 12:17:49', '2026-02-05 12:17:49'),
(2, 'How can I place an export order with We Care India Group?', 'Simply fill out our enquiry form, email us, or contact our export specialists for a personalized quote and order process.', 'active', '2026-02-05 12:35:02', '2026-02-05 12:35:02'),
(3, 'Do you provide custom branding/private labels for bulk buyers?', 'Yes, we offer private labeling and branding solutions for our international wholesale clients.', 'active', '2026-02-05 12:35:36', '2026-02-05 12:35:36'),
(4, 'Do you provide custom branding/private labels for bulk buyers?', '<p>Yes, we offer private labeling and branding solutions for our international wholesale clients.</p>', 'active', '2026-02-10 23:06:20', '2026-02-13 11:42:00'),
(5, 'How do you ensure product quality and compliance?', '<p>Our bedsheets are manufactured to international standards and undergo strict quality checks before export. Certifications and compliance documentation are available upon request.</p>', 'active', '2026-02-10 23:07:15', '2026-02-13 11:41:17');

