INSERT INTO `popular_works` (`id`, `title`, `description`, `status`, `created_at`, `updated_at`) VALUES
(1, 'World Fertility Services', '<p><span style=\"color: rgb(51, 51, 51); font-family: Neue, sans-serif; font-size: 15px;\">We specialize in offering advanced fertility solutions tailored to your unique needs, guiding and supporting you every step of the way on your journey toward starting or growing your family.</span></p>', 'active', '2026-02-13 12:08:20', '2026-02-13 12:08:20'),
(2, 'Select IVF', '<p><span style=\"color: rgb(51, 51, 51); font-family: Neue, sans-serif; font-size: 15px;\">Your trusted partner in IVF and infertility treatments, dedicated to providing personalized care and achieving high success rates to help you realize your dream of parenthood.</span></p>', 'active', '2026-02-13 12:10:33', '2026-02-13 12:10:33'),
(3, 'Go IVF Surrogacy', '<p><span style=\"color: rgb(51, 51, 51); font-family: Neue, sans-serif; font-size: 15px;\">Your trusted partner in IVF and infertility treatments, dedicated to providing personalized care and achieving high success rates to help you realize your dream of parenthood.</span></p>', 'active', '2026-02-13 12:11:00', '2026-02-13 12:11:00'),
(4, 'We Care India', '<p><span style=\"color: rgb(51, 51, 51); font-family: Neue, sans-serif; font-size: 15px;\">A one-stop solution for medical treatments, surgeries, and wellness care offers comprehensive services to cater to all aspects of a patient\'s healthcare journey, from diagnosis to recovery.</span></p>', 'active', '2026-02-13 12:11:29', '2026-02-13 12:11:29'),
(5, 'We Care IVF Surrogacy', '<p><span style=\"color: rgb(51, 51, 51); font-family: Neue, sans-serif; font-size: 15px;\">Blending professional expertise with heartfelt compassion to help you navigate your fertility journey and make your dreams of parenthood a reality.</span></p>', 'active', '2026-02-13 12:11:55', '2026-02-13 12:11:55'),
(6, 'India Health Tour', '<p><span style=\"color: rgb(51, 51, 51); font-family: Neue, sans-serif; font-size: 15px;\">India has become a global hub for medical tourism, offering world-className healthcare services to international patients. The country boasts state-of-the-art medical facilities, highly skilled healthcare</span></p>', 'active', '2026-02-13 12:12:20', '2026-02-13 12:12:20');

