INSERT INTO `products` (`id`, `category_id`, `blog_category_id`, `product_name`, `slug`, `short_description`, `long_description`, `image`, `status`, `created_at`, `updated_at`) VALUES
(1, 1, NULL, 'Best Acrylic blanket exporter from India', 'acrylic-blanket-exporter-from-india', 'short data', '<span style=\"color: rgb(0, 0, 0); font-family: Neue, sans-serif; font-size: 15px; background-color: rgb(122, 204, 231);\">We are a leading company from India, committed to excellence and innovation across diverse sectors. With a strong foundation of trust and quality, we cater to global markets, offering top-tier products, services, and solutions.From being a major exporter to promoting world-class medical tourism and enhancing e-commerce within India, our mission is to deliver value, bridge borders, and drive growth.</span>', 'product/698abfaf3e658.webp', 'active', '2026-02-04 12:42:51', '2026-02-11 04:12:35'),
(2, 1, NULL, 'Open Bath Slippers Exporter from India', 'Open Bath Slippers Exporter from India', 'India has become a global hub for manufacturing hotel amenities, especially open bath slippers used in resorts, spas, wellness centers, guest houses, and premium hotels. These slippers are lightweight, hygienic, water-resistant, and designed for comfort and safety in wet bathroom areas. International buyers prefer working with an open bath slippers exporter from India because Indian suppliers offer high-quality materials, advanced production methods, competitive pricing, and large-scale export capabilities. \r\n\r\nOpen bath slippers come in various materials like terry cloth, microfiber, EVA, rubber, and non-woven fabric. Exporters also provide customization options such as logo printing, color selection, GSM variations, and branded packaging. With a strong supply chain, skilled labor, and efficient export documentation, Indian manufacturers supply millions of slipper pairs to countries across Europe, the Middle East, the USA, Asia, and Africa.', 'India has become a global hub for manufacturing hotel amenities, especially open bath slippers used in resorts, spas, wellness centers, guest houses, and premium hotels. These slippers are lightweight, hygienic, water-resistant, and designed for comfort and safety in wet bathroom areas. International buyers prefer working with an open bath slippers exporter from India because Indian suppliers offer high-quality materials, advanced production methods, competitive pricing, and large-scale export capabilities. \r\n\r\nOpen bath slippers come in various materials like terry cloth, microfiber, EVA, rubber, and non-woven fabric. Exporters also provide customization options such as logo printing, color selection, GSM variations, and branded packaging. With a strong supply chain, skilled labor, and efficient export documentation, Indian manufacturers supply millions of slipper pairs to countries across Europe, the Middle East, the USA, Asia, and Africa.', 'product/698c5029492d2.webp', 'active', '2026-02-04 12:47:45', '2026-02-11 04:17:21');

