INSERT INTO `setting` (`id`, `first_heading`, `second_heading`, `section_one_content`, `section_one_image`, `experience_image`, `experience_heading`, `experience_description`, `testimonial_heading`, `popular_heading`, `logo`, `favicon`, `email`, `phone`, `address`, `facebook`, `twitter`, `linkedin`, `instagram`, `footer_heading`, `footer_description`, `created_at`, `updated_at`) VALUES
(1, 'We Care India Top 10', 'Exporter Company from India', '<p>We are a leading company from India, committed to excellence and innovation across diverse sectors. With a strong foundation of trust and quality, we cater to global markets, offering top-tier products, services, and solutions.From being a major exporter to promoting world-class medical tourism and enhancing e-commerce within India, our mission is to deliver value, bridge borders, and drive growth.</p>', 'settings/1776438417_global-communication.mp4', 'settings/1771232361_We-Care-India-Group.webp', '<p>Experience Compassionate Care in Global Trade</p>', '<p>We Care India is dedicated to transforming global trade with a unique blend of professionalism and compassion. Specializing in import and export services, we ensure seamless logistics, high-quality products, and customer satisfaction. Our commitment to excellence and ethical practices positions us as a trusted partner in international trade. With We Care India, you experience not just business but care that goes beyond borders.</p>', '<p>What people says about We Care India Group</p>', 'Explore Our Global Trade Success Stories', 'settings/1770409060_we-care-logo.jpg', 'settings/1770698988_we-care-logo.jpg', 'vineetpatel907@gmail.com', '9074072262', 'House No.78 Pathra Umariya', '#facebook', '#twitter', 'https://www.linkedin.com/in/vineet-kachhi-538951121/1', NULL, 'We Care India Group', 'We are a leading company from India, committed to excellence and innovation across diverse sectors. With a strong foundation of trust and quality, we cater to global markets, offering top-tier products, services, and solutions.From being a major exporter to promoting world-class medical tourism and enhancing e-commerce within India, our mission is to deliver value, bridge borders, and drive growth.', NULL, '2026-04-17 09:53:18');

