INSERT INTO `testimonials` (`id`, `client_name`, `client_location`, `message`, `image`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Alice Patterson, Vancouver', 'Canada', 'We Care India Group has been an exceptional partner in our import-export journey. Their professionalism, attention to detail, and commitment to quality have made them a trusted ally in our global trade endeavors.', 'testimonial/1770991809_canada.webp', 'active', '2026-02-13 08:40:09', '2026-02-13 11:06:34'),
(2, 'Robert Martinez, Miami', 'USA', 'We Care India Group provides premium king size and super king size bedsheets perfect for the American market. Fast, secure shipments and all compliance documents were well managed. As a US wholesaler, consistency and quality have made this team our preferred exporter.', 'testimonial/1771002018_usa.webp', 'active', '2026-02-13 11:30:18', '2026-02-13 11:30:18'),
(3, 'Chloe Evans, Melbourne', 'Australia', '<p>Our business in Australia relies on timely import of fine cotton bedsheets for consumers who demand luxury and durability. We Care India Group handled every export order with professionalism. Designs like dust grey and blue patterns are especially popular with our clients!</p>', 'testimonial/1771002142_Australia.webp', 'active', '2026-02-13 11:32:22', '2026-02-13 11:32:22'),
(4, 'Peter Mwangi, Nairobi', 'Kenya', '<p>Working with We Care India Group made sourcing Indian bedsheets for our retail chain in Kenya very easy. The diverse product catalog, competitive pricing, and high-grade fabric impressed both us and our customers. Looking forward to growing our imports!</p>', 'testimonial/1771002214_kenya.webp', 'active', '2026-02-13 11:33:34', '2026-02-13 11:33:34');

